from lfx.custom.custom_component.component import Component
from lfx.io import DataFrameInput, Output
from lfx.schema.dataframe import DataFrame

import pandas as pd
import os
import logging

logger = logging.getLogger(__name__)


class OfficeToMarkdown(Component):
    """
    Reads an MS Office file (DOCX, PPTX, XLSX) saved by FastAPI and
    converts it to Markdown using markitdown.

    Input:  Single-row DataFrame from APIPipelineInput
            (must contain file_path)
    Output: Same row with added column:
            - markdown: Markdown representation of the file
    """

    display_name = "2) Office → Markdown"
    description = (
        "Converts an MS Office file (DOCX, PPTX, XLSX) to Markdown "
        "using markitdown. Returns the input row with an added "
        "'markdown' column."
    )

    inputs = [
        DataFrameInput(
            name="dataframe",
            display_name="Input Metadata Row",
            info="Single-row DataFrame from APIPipelineInput with file_path.",
        ),
    ]

    outputs = [
        Output(
            name="result",
            display_name="Enriched DataFrame",
            method="process",
            type=DataFrame,
        )
    ]

    # Supported extensions
    _SUPPORTED = {".docx", ".pptx", ".xlsx"}

    def process(self) -> DataFrame:
        try:
            df = self.dataframe

            if not isinstance(df, pd.DataFrame) or df.empty:
                return self._error_df("Empty or invalid input", None)

            meta = df.iloc[0].to_dict()
            file_path = meta.get("file_path")

            # ── Validate ─────────────────────────────────────
            if not file_path:
                return self._error_df("No file_path in input", meta)

            if not os.path.exists(file_path):
                return self._error_df(f"File not found: {file_path}", meta)

            ext = os.path.splitext(file_path)[1].lower()
            if ext not in self._SUPPORTED:
                return self._error_df(
                    f"Unsupported file type: {ext}. "
                    f"Expected: {', '.join(sorted(self._SUPPORTED))}",
                    meta,
                )

            # ── Convert to Markdown (markitdown) ─────────────
            markdown_text = self._convert(file_path)

            if not markdown_text or not markdown_text.strip():
                return self._error_df("Empty Markdown output", meta)

            # ── Build output row ─────────────────────────────
            result_df = df.copy()
            result_df["markdown"] = markdown_text
            result_df["error_reason"] = None

            logger.info(
                f"[OFFICE→MD] file={os.path.basename(file_path)} "
                f"ext={ext} markdown={len(markdown_text)} chars"
            )

            return DataFrame(result_df)

        except Exception as e:
            logger.error(f"[OFFICE→MD] Exception: {e}")
            return self._error_df(
                f"Exception: {str(e)}",
                meta if "meta" in dir() else None,
            )

    # ═════════════════════════════════════════════════════════
    # CONVERSION
    # ═════════════════════════════════════════════════════════

    def _convert(self, file_path: str) -> str:
        """Convert Office file to Markdown using markitdown."""
        from markitdown import MarkItDown

        md = MarkItDown()
        result = md.convert(file_path)

        return result.text_content or ""

    # ═════════════════════════════════════════════════════════
    # ERROR HANDLING
    # ═════════════════════════════════════════════════════════

    def _error_df(self, message: str, meta: dict = None) -> DataFrame:
        logger.warning(f"[OFFICE→MD] {message}")

        if meta:
            row = dict(meta)
        else:
            row = {}

        row["markdown"] = None
        row["error_reason"] = message

        return DataFrame(pd.DataFrame([row]))
